"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { monotonePath, usePrefersReducedMotion } from "@/components/moneytrees/charts/chart-engine";

export type TickerPoint = { time: number; price: number };

const SPARK_W = 200;

/** Tiny, dependency-free price sparkline: bull/bear stroke, gradient fill, draw-in reveal. */
export function Sparkline({
  data,
  className,
  height = 40,
  strokeWidth = 1.5,
}: {
  data: TickerPoint[];
  className?: string;
  height?: number;
  strokeWidth?: number;
}) {
  const reduce = usePrefersReducedMotion();
  const id = React.useId().replace(/:/g, "");
  const up = data.length >= 2 && data[data.length - 1]!.price >= data[0]!.price;
  const color = up ? "var(--spectrum-chart-up)" : "var(--spectrum-chart-down)";

  const path = React.useMemo(() => {
    if (data.length < 2) return null;
    let lo = Infinity;
    let hi = -Infinity;
    for (const p of data) {
      lo = Math.min(lo, p.price);
      hi = Math.max(hi, p.price);
    }
    const span = hi - lo || 1;
    const points = data.map((p, i) => ({
      x: (i / (data.length - 1)) * SPARK_W,
      y: 2 + (1 - (p.price - lo) / span) * (height - 4),
    }));
    const line = monotonePath(points);
    return { line, area: `${line}L${SPARK_W},${height}L0,${height}Z` };
  }, [data, height]);

  if (!path) return null;

  return (
    <svg
      viewBox={`0 0 ${SPARK_W} ${height}`}
      preserveAspectRatio="none"
      className={cn("block w-full", className)}
      style={{ height }}
      aria-hidden
    >
      <defs>
        <linearGradient id={`${id}-fill`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity={0.45} />
          <stop offset="100%" stopColor={color} stopOpacity={0} />
        </linearGradient>
        {!reduce && (
          <clipPath id={`${id}-reveal`}>
            <rect x="0" y="0" width={SPARK_W} height={height}>
              <animate attributeName="width" from="0" to={SPARK_W} dur="0.25s" fill="freeze" />
            </rect>
          </clipPath>
        )}
      </defs>
      <g clipPath={reduce ? undefined : `url(#${id}-reveal)`}>
        <path d={path.area} fill={`url(#${id}-fill)`} />
        <path
          d={path.line}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinejoin="round"
          strokeLinecap="round"
          vectorEffect="non-scaling-stroke"
        />
      </g>
    </svg>
  );
}
